"""Source-bound, CPU-only checks for the proposed pedestrian crossing site.

These checks describe recorded geometry and device operation. They do not decide
whether a device is legally official, intersections legally adjacent, or an
exception under NRS 484B.290 applies.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


def _source(packet: dict, key: str) -> dict:
    source = packet.get("sources", {}).get(key)
    if not isinstance(source, dict) or not source.get("path") or not source.get("sha256"):
        raise ValueError(f"missing source binding: {key}")
    path = Path(source["path"])
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != source["sha256"]:
        raise ValueError(f"source hash mismatch: {key}")
    expected = {
        "map": {"junctions": packet.get("junctions"), "between_edge": packet.get("between_edge"), "intervening_junction_ids": packet.get("intervening_junction_ids"), "highway_banks": packet.get("highway_banks")},
        "route": {"pedestrian_route": packet.get("pedestrian_route"), "crossing": packet.get("crossing")},
        "devices": packet.get("devices"),
        "markings": packet.get("markings"),
        "highway": packet.get("highway"),
    }[key]
    try:
        actual = json.loads(path.read_text())
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"invalid source content: {key}") from exc
    if actual != expected:
        raise ValueError(f"source content mismatch: {key}")
    return source


def _point(value) -> tuple[float, float]:
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("expected planar point")
    point = tuple(float(v) for v in value)
    if not all(math.isfinite(v) for v in point):
        raise ValueError("nonfinite point")
    return point


def _cross(a, b, c) -> float:
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _intersects(a, b, c, d) -> bool:
    # Collinear or endpoint contact is deliberately inconclusive for this probe.
    x, y = _cross(a, b, c), _cross(a, b, d)
    z, w = _cross(c, d, a), _cross(c, d, b)
    return x * y < 0 and z * w < 0


def assess_site(packet: dict, *, require_operating: bool = True) -> dict:
    for name in ("map", "route", "devices", "markings", "highway"):
        _source(packet, name)
    if packet.get("coordinate_frame") != "map_xy_m":
        raise ValueError("unsupported coordinate frame")
    highway = packet["highway"]
    if not highway.get("boundary_document_id") or not highway.get("public_access_document_id"):
        raise ValueError("highway status provenance missing")
    junctions = packet["junctions"]
    if len(junctions) != 2 or len({j["id"] for j in junctions}) != 2:
        raise ValueError("two distinct junctions required")
    a, b = junctions
    if packet.get("between_edge") != [a["id"], b["id"]] or packet.get("intervening_junction_ids") != []:
        raise ValueError("no source-supported direct segment between junctions")
    aa, bb = _point(a["center"]), _point(b["center"])
    segment = (bb[0] - aa[0], bb[1] - aa[1])
    norm = segment[0] ** 2 + segment[1] ** 2
    if norm <= 0:
        raise ValueError("coincident junctions")
    route = [_point(p) for p in packet["pedestrian_route"]]
    if len(route) < 2:
        raise ValueError("route too short")
    crossing = packet["crossing"]
    entry, exit = _point(crossing["entry"]), _point(crossing["exit"])
    if entry not in route or exit not in route or route.index(entry) >= route.index(exit):
        raise ValueError("crossing not an ordered part of route")
    # The midpoint must lie strictly between source-defined junction envelope radii.
    mid = ((entry[0] + exit[0]) / 2, (entry[1] + exit[1]) / 2)
    t = ((mid[0] - aa[0]) * segment[0] + (mid[1] - aa[1]) * segment[1]) / norm
    distance = math.sqrt(norm)
    if not float(a["envelope_radius_m"]) / distance < t < 1 - float(b["envelope_radius_m"]) / distance:
        raise ValueError("crossing midpoint not between intersection envelopes")
    banks = [(_point(x), _point(y)) for x, y in packet["highway_banks"]]
    if len(banks) != 2 or not all(_intersects(entry, exit, x, y) for x, y in banks):
        raise ValueError("route does not cross both highway banks")
    devices = packet["devices"]
    if {d["junction_id"] for d in devices} != {a["id"], b["id"]} or len(devices) != 2:
        raise ValueError("device required at each junction")
    start, end = (float(v) for v in crossing["time_s"])
    if not math.isfinite(start) or not math.isfinite(end) or start >= end:
        raise ValueError("invalid crossing interval")
    operation = []
    for device in devices:
        if not all(device.get(k) for k in ("device_id", "authority_record_id", "placement_record_id", "purpose_record_id", "governing_participants", "instructions")):
            raise ValueError("device provenance or governance missing")
        windows = device.get("operating_intervals_s", [])
        observed = any(float(lo) <= start and float(hi) >= end for lo, hi in windows)
        operation.append(observed)
        if require_operating and not observed:
            raise ValueError("device operation not established throughout crossing")
    markings = packet["markings"]
    if markings.get("survey_complete") is not True:
        raise ValueError("marked-crosswalk survey incomplete")
    marked_ids = []
    for m in markings.get("marked_crosswalks", []):
        if not m.get("marking_id") or not m.get("survey_record_id"):
            raise ValueError("marking provenance missing")
        lo, hi = (float(v) for v in m["between_edge_station_fraction"])
        if lo <= t <= hi:
            marked_ids.append(m["marking_id"])
    return {
        "between_junction_ids": [a["id"], b["id"]],
        "crossing_station_fraction": t,
        "crosses_both_highway_banks": True,
        "device_ids": sorted(d["device_id"] for d in devices),
        "device_operation_observed": all(operation),
        "marked_crosswalk_ids_at_crossing": sorted(marked_ids),
        "marked_crosswalk_present": bool(marked_ids),
        "legal_adjacency": "undetermined",
        "legal_official_status": "undetermined",
        "nrs_484b_290_exception": "undetermined",
        "source_sha256": {k: packet["sources"][k]["sha256"] for k in ("map", "route", "devices", "markings", "highway")},
    }


def assess_file(path: str | Path) -> dict:
    return assess_site(json.loads(Path(path).read_text()))

"""Original 20 Hz walker and device observations for a selected exact case.

The caller supplies the real CARLA world, walker, and a device reader. The
reader must return original device identity and operating state after each
world tick. This module does not decide legal official status or exceptions.
"""

from __future__ import annotations

import hashlib
import json
import math
from io import BytesIO
from pathlib import Path
from zipfile import ZIP_STORED, ZipFile

from PIL import Image

from site_geometry import assess_site

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
CAMERA_DIMENSIONS = {"overview": (1920, 1080), "approach": (1280, 720),
                     "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _image_bytes(reader, frame: int, dimensions: tuple[int, int]) -> bytes:
    sample = reader(frame)
    if not isinstance(sample, dict) or sample.get("frame") != frame:
        raise ValueError("original camera frame identity mismatch")
    payload = sample.get("png_bytes")
    if not isinstance(payload, bytes) or not payload.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("original camera PNG missing")
    with Image.open(BytesIO(payload)) as image:
        image.verify()
    with Image.open(BytesIO(payload)) as image:
        if image.format != "PNG" or image.size != dimensions:
            raise ValueError("original camera dimensions mismatch")
        image.load()
    return payload


def _canonical(value: dict) -> bytes:
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()


def capture_observation(world, walker, packet: dict, case_id: str, output: str | Path,
                        read_device, *, ticks: int = 900, camera_readers=None,
                        camera_dimensions=None, before_tick=None,
                        after_tick=None) -> dict:
    """Write original observations; ``ticks`` is injectable for CPU fixtures."""
    site = assess_site(packet, require_operating=False)
    if not isinstance(case_id, str) or not case_id:
        raise ValueError("exact case ID required")
    if not isinstance(ticks, int) or ticks < 2:
        raise ValueError("at least two Native ticks required")
    if not callable(read_device):
        raise ValueError("device reader required")
    if before_tick is not None and not callable(before_tick):
        raise ValueError("before-tick route controller must be callable")
    if after_tick is not None and not callable(after_tick):
        raise ValueError("after-tick original graph capture must be callable")
    expected = set(site["device_ids"])
    packet_sha = hashlib.sha256(_canonical(packet)).hexdigest()
    frames = []
    path = Path(output)
    if path.exists():
        raise ValueError("original observation output exists")
    if camera_readers is not None and set(camera_readers) != set(CAMERAS):
        raise ValueError("four named camera readers required")
    dimensions = camera_dimensions or CAMERA_DIMENSIONS
    if set(dimensions) != set(CAMERAS):
        raise ValueError("four named camera dimensions required")
    media_paths = {name: path.parent / (path.stem + "." + name + ".png.zip")
                   for name in CAMERAS} if camera_readers is not None else {}
    if any(p.exists() for p in media_paths.values()):
        raise ValueError("original camera output exists")
    path.parent.mkdir(parents=True, exist_ok=True)
    archives = {name: ZipFile(p, "w", compression=ZIP_STORED)
                for name, p in media_paths.items()}
    previous_frame = None
    previous_time = None
    try:
      for _ in range(ticks):
        if before_tick is not None:
            before_tick()
        tick_frame = int(world.tick())
        snapshot = world.get_snapshot()
        frame = int(snapshot.frame)
        time_s = float(snapshot.timestamp.elapsed_seconds)
        if frame != tick_frame or (previous_frame is not None and frame != previous_frame + 1):
            raise ValueError("Native frame discontinuity")
        if not math.isfinite(time_s) or (previous_time is not None and not 0.049 <= time_s - previous_time <= 0.051):
            raise ValueError("Native 20 Hz clock discontinuity")
        position = walker.get_location()
        xyz = [float(position.x), float(position.y), float(position.z)]
        if not all(math.isfinite(v) for v in xyz):
            raise ValueError("invalid original walker position")
        readings = [read_device(device_id) for device_id in sorted(expected)]
        if {r.get("device_id") for r in readings} != expected or len(readings) != len(expected):
            raise ValueError("device identity readback mismatch")
        for r in readings:
            if not isinstance(r.get("actor_id"), int) or r["actor_id"] < 0:
                raise ValueError("device actor identity missing")
            if not isinstance(r.get("state"), str) or not r["state"]:
                raise ValueError("device state readback missing")
            if type(r.get("is_operating")) is not bool:
                raise ValueError("device operation readback missing")
        row = {"frame": frame, "time_s": time_s, "walker_xyz_m": xyz,
               "devices": readings}
        if camera_readers is not None:
            row["camera_frames"] = {}
            for name in CAMERAS:
                payload = _image_bytes(camera_readers[name], frame, tuple(dimensions[name]))
                member = f"{frame:08d}.png"
                archives[name].writestr(member, payload)
                row["camera_frames"][name] = {"member": member,
                                              "sha256": hashlib.sha256(payload).hexdigest()}
        if after_tick is not None:
            after_tick(frame, time_s, row)
        frames.append(row)
        previous_frame, previous_time = frame, time_s
    finally:
        for archive in archives.values():
            archive.close()
        if len(frames) != ticks:
            for media_path in media_paths.values():
                media_path.unlink(missing_ok=True)
    document = {"format": "original-pedestrian-site-observation", "case_id": case_id,
                "packet_sha256": packet_sha, "source_sha256": site["source_sha256"],
                "frame_count": ticks, "frames": frames,
                "camera_sources": {name: {"path": str(media_path),
                    "sha256": hashlib.sha256(media_path.read_bytes()).hexdigest(),
                    "frame_count": ticks, "dimensions": list(dimensions[name])}
                    for name, media_path in media_paths.items()}}
    path.write_bytes(_canonical(document))
    return {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "frame_count": ticks, "case_id": case_id,
            "camera_capture_complete": camera_readers is not None}


def analyze_saved(packet: dict, receipt: dict, *, expected_case_id: str,
                  required_frames: int = 900) -> dict:
    """Reject stale/partial original observations and summarize measured motion."""
    site = assess_site(packet, require_operating=False)
    path = Path(receipt["path"])
    data = path.read_bytes()
    if hashlib.sha256(data).hexdigest() != receipt.get("sha256"):
        raise ValueError("original observation hash mismatch")
    document = json.loads(data)
    if document.get("format") != "original-pedestrian-site-observation" or document.get("case_id") != expected_case_id or receipt.get("case_id") != expected_case_id:
        raise ValueError("exact observation case mismatch")
    if document.get("packet_sha256") != hashlib.sha256(_canonical(packet)).hexdigest() or document.get("source_sha256") != site["source_sha256"]:
        raise ValueError("site source binding mismatch")
    frames = document.get("frames")
    if (not isinstance(frames, list) or len(frames) != required_frames or
            document.get("frame_count") != required_frames or receipt.get("frame_count") != required_frames):
        raise ValueError("original observation frame count mismatch")
    expected = set(site["device_ids"])
    positions = []
    all_operating = True
    previous_frame = previous_time = None
    for sample in frames:
        frame, time_s = sample["frame"], sample["time_s"]
        if not isinstance(frame, int) or (previous_frame is not None and frame != previous_frame + 1):
            raise ValueError("saved frame discontinuity")
        if not isinstance(time_s, (int, float)) or not math.isfinite(time_s) or (previous_time is not None and not 0.049 <= time_s - previous_time <= 0.051):
            raise ValueError("saved 20 Hz clock discontinuity")
        xyz = sample["walker_xyz_m"]
        if len(xyz) != 3 or not all(isinstance(x, (int, float)) and math.isfinite(x) for x in xyz):
            raise ValueError("saved walker position missing")
        readings = sample["devices"]
        if len(readings) != len(expected) or {r["device_id"] for r in readings} != expected:
            raise ValueError("saved device identity mismatch")
        if any(not isinstance(r.get("actor_id"), int) or r["actor_id"] < 0 or not isinstance(r.get("state"), str) or not r["state"] or type(r.get("is_operating")) is not bool for r in readings):
            raise ValueError("saved device readback missing")
        all_operating &= all(r["is_operating"] for r in readings)
        positions.append(xyz)
        previous_frame, previous_time = frame, time_s
    def crossing_segments(bank):
        a, b = bank
        def cross(p, q, r):
            return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
        return [i for i, (p, q) in enumerate(zip(positions, positions[1:]))
                if cross(a, b, p) * cross(a, b, q) < 0 and
                cross(p, q, a) * cross(p, q, b) < 0]
    crossings = [crossing_segments(bank) for bank in packet["highway_banks"]]
    if not all(crossings):
        raise ValueError("walker did not cross both observed highway banks")
    first, last = min(min(indices) for indices in crossings), max(max(indices) for indices in crossings) + 1
    during_crossing = all(r["is_operating"] for sample in frames[first:last + 1]
                          for r in sample["devices"])
    return {"case_id": expected_case_id, "frame_count": required_frames,
            "original_observation_sha256": receipt["sha256"],
            "crossed_both_highway_banks": True, "both_devices_operating_all_frames": all_operating,
            "both_devices_operating_during_crossing": during_crossing,
            "observed_crossing_frame_range": [frames[first]["frame"], frames[last]["frame"]],
            "observed_crossing_time_s": [frames[first]["time_s"], frames[last]["time_s"]],
            "marked_crosswalk_present_in_survey": site["marked_crosswalk_present"],
            "legal_adjacency": "undetermined", "legal_official_status": "undetermined",
            "nrs_484b_290_exception": "undetermined"}

"""Lazy CARLA readback bridge for exact site observations.

Callers own actor creation and cleanup. Operation is supplied from an original
device-health source; a displayed traffic-light color alone cannot establish it.
"""

from __future__ import annotations

from collections import deque
from io import BytesIO

from PIL import Image

from native_observation import CAMERAS, CAMERA_DIMENSIONS


class CameraFrames:
    """Join four CARLA BGRA callbacks to the frame returned by world.tick()."""

    def __init__(self, dimensions=None, *, max_pending=4):
        self.dimensions = dict(dimensions or CAMERA_DIMENSIONS)
        if set(self.dimensions) != set(CAMERAS):
            raise ValueError("four named camera dimensions required")
        if not isinstance(max_pending, int) or max_pending < 1:
            raise ValueError("positive camera buffer bound required")
        self.max_pending = max_pending
        self.pending = {name: {} for name in CAMERAS}
        self.order = {name: deque() for name in CAMERAS}

    def callback(self, name):
        if name not in self.pending:
            raise ValueError("unknown camera name")

        def receive(image):
            frame = int(image.frame)
            width, height = self.dimensions[name]
            if (image.width, image.height) != (width, height):
                raise ValueError("original camera dimensions mismatch")
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError("original BGRA byte count mismatch")
            if frame in self.pending[name]:
                raise ValueError("duplicate original camera frame")
            decoded = Image.frombytes("RGBA", (width, height), raw, "raw", "BGRA").convert("RGB")
            stream = BytesIO()
            decoded.save(stream, format="PNG")
            self.pending[name][frame] = stream.getvalue()
            self.order[name].append(frame)
            if len(self.order[name]) > self.max_pending:
                old = self.order[name].popleft()
                del self.pending[name][old]

        return receive

    def reader(self, name):
        if name not in self.pending:
            raise ValueError("unknown camera name")

        def read(frame):
            if frame not in self.pending[name]:
                raise ValueError("original camera frame unavailable")
            self.order[name].remove(frame)
            return {"frame": frame, "png_bytes": self.pending[name].pop(frame)}

        return read

    def readers(self):
        return {name: self.reader(name) for name in CAMERAS}


def device_reader(packet, actors, operation_readback):
    """Bind each source device ID to its own CARLA actor and health readback."""
    expected = {d["device_id"] for d in packet["devices"]}
    if set(actors) != expected or not callable(operation_readback):
        raise ValueError("source-bound device actors and operation reader required")
    actor_ids = [a.id for a in actors.values()]
    if (any(type(actor_id) is not int or actor_id < 0 for actor_id in actor_ids)
            or len(set(actor_ids)) != len(actor_ids)):
        raise ValueError("distinct original device actor identities required")

    def read(device_id):
        if device_id not in expected:
            raise ValueError("unknown source device ID")
        actor = actors[device_id]
        state = str(actor.get_state())
        operating = operation_readback(device_id, actor)
        if not state or type(operating) is not bool:
            raise ValueError("original device state or operation unavailable")
        return {"device_id": device_id, "actor_id": actor.id,
                "state": state, "is_operating": operating}

    return read

"""Independent observed-source comparison for exact crossing cases."""

from site_geometry import assess_site


def compare_marking_cases(unmarked: dict, marked: dict) -> dict:
    left, right = assess_site(unmarked), assess_site(marked)
    if left["marked_crosswalk_present"] or not right["marked_crosswalk_present"]:
        raise ValueError("marking difference not observed")
    fixed = ("between_junction_ids", "device_ids", "device_operation_observed", "crosses_both_highway_banks")
    if any(left[k] != right[k] for k in fixed):
        raise ValueError("comparison site or operating controls changed")
    for source in ("map", "route", "devices", "highway"):
        if left["source_sha256"][source] != right["source_sha256"][source]:
            raise ValueError(f"fixed source changed: {source}")
    if abs(left["crossing_station_fraction"] - right["crossing_station_fraction"]) > 1e-9:
        raise ValueError("crossing station changed")
    return {"comparison_id": "between_intersections_marking", "case_status": "source_measurements_compared", "unmarked": left, "marked": right}


def compare_operation_cases(operating: dict, inactive: dict) -> dict:
    left = assess_site(operating)
    right = assess_site(inactive, require_operating=False)
    if right["device_operation_observed"]:
        raise ValueError("inactive device difference not observed")
    for key in ("between_junction_ids", "crossing_station_fraction", "crosses_both_highway_banks", "device_ids", "marked_crosswalk_present"):
        if left[key] != right[key]:
            raise ValueError(f"fixed condition changed: {key}")
    for source in ("map", "route", "markings", "highway"):
        if left["source_sha256"][source] != right["source_sha256"][source]:
            raise ValueError(f"fixed source changed: {source}")
    return {"comparison_id": "both_devices_operating", "case_status": "source_measurements_compared", "operating": left, "inactive": right}


def compare_delivery_audits(comparison_id: str, first: dict, second: dict) -> dict:
    """Require two distinct sealed attempts and only the declared source change."""
    from delivery_audit import CASES

    cases = {
        "between_intersections_marking": (
            "midblock_unmarked_operating", "midblock_marked_operating", "markings"),
        "both_devices_operating": (
            "midblock_unmarked_operating", "midblock_unmarked_inactive", "devices"),
    }
    if comparison_id not in cases:
        raise ValueError("unknown exact comparison")
    left_suffix, right_suffix, changing_source = cases[comparison_id]
    rows = (first, second)
    if any(row.get("format") != "worker-pedestrian-delivery-audit" or
           row.get("case_id") not in CASES or row.get("diagnostic_fixture") is not False or
           not isinstance(row.get("native_provenance"), dict) for row in rows):
        raise ValueError("two sealed original delivery audits required")
    if not first["case_id"].endswith(left_suffix) or not second["case_id"].endswith(right_suffix):
        raise ValueError("comparison exact case ordering differs")
    if first["source_observation_sha256"] == second["source_observation_sha256"] or \
       first["native_provenance"]["seal_sha256"] == second["native_provenance"]["seal_sha256"]:
        raise ValueError("comparison requires two distinct original Native attempts")
    if first["frame_count"] != second["frame_count"] or \
       first["camera_names"] != second["camera_names"] or \
       first["full_pixel_decodes"] != second["full_pixel_decodes"]:
        raise ValueError("comparison duration or camera policy changed")
    for source in ("map", "route", "devices", "markings", "highway"):
        if source != changing_source and first["source_sha256"][source] != second["source_sha256"][source]:
            raise ValueError("fixed comparison source changed: " + source)
    if changing_source == "markings":
        if first["marked_crosswalk_observed"] or not second["marked_crosswalk_observed"] or \
           not first["both_devices_operating_during_crossing"] or \
           not second["both_devices_operating_during_crossing"]:
            raise ValueError("marked crossing distinction absent")
    elif first["marked_crosswalk_observed"] or second["marked_crosswalk_observed"] or \
         not first["both_devices_operating_during_crossing"] or \
         second["both_devices_operating_during_crossing"]:
        raise ValueError("device operation distinction absent")
    return {"comparison_id": comparison_id, "case_ids": [first["case_id"], second["case_id"]],
            "sealed_attempts_compared": True, "legal_verdict": None,
            "physical_acceptance": False}

